    - the X argument is an array of tuples of the form X=[,...,(xi_1,xi_2),...]
    """
def model_function(X: Any, a: Any, b: Any, c: Any) -> object {
    (nw1, nw2, I) = X;
    f = (a * pow(I, 2) * (nw1 + 0.5)) + (b * I * (nw2 + 0.5)) + c;
    return f;
}

"""
