    Output : Predicted output based on estimated intercept, slope and input feature
    """
def get_regression_predictions(
    input_feature: Any, intercept: Any, slope: Any
) -> object {
    predicted_output = intercept + (slope * input_feature);
    return predicted_output;
}

"""Break str `s` into a list of str.

    1. `s` has all of its peripheral whitespace removed.
    1. `s` is downcased with `lower`.
    2. `s` is split on whitespace.
    3. For each token, any peripheral punctuation on it is stripped
       off. Punctuation is here defined by `string.punctuation`.

    Parameters
    ----------
    s : str
        The string to tokenize.

    Returns
    -------
    list of str

    """
def simple(s: Any) -> object {
    import string;
    punct = string.punctuation;
    final_toks = [];
    toks = s.lower().strip().split();
    for w in toks {
        final_toks.append(w.strip(punct));
    }
    return final_toks;
}

"""
    This is taken from Python 3.7's inspect.py; the only change is to
    add documentation.

    INPUT:

    - ``annotation`` -- annotation for a function
    - ``base_module`` (optional, default ``None``)

    This is only relevant with Python 3, so the doctests are marked
    accordingly.

    EXAMPLES::

        sage: from sage.misc.sageinspect import formatannotation
        sage: import inspect
        sage: def foo(a, *, b:int, **kwargs): # py3
        ....:     pass
        sage: s = inspect.signature(foo) # py3

        sage: a = s.parameters['a'].annotation # py3
        sage: a # py3
        <class 'inspect._empty'>
        sage: formatannotation(a) # py3
        'inspect._empty'

        sage: b = s.parameters['b'].annotation # py3
        sage: b # py3
        <class 'int'>
        sage: formatannotation(b) # py3
        'int'
    """
def formatannotation(annotation: Any, base_module: Any = None) -> object {
    if (getattr(annotation, '__module__', None) == 'typing') {
        return repr(annotation).replace('typing.', '');
    }
    if isinstance(annotation, `type) {
        if (annotation.__module__ in ('builtins', base_module)) {
            return annotation.__qualname__;
        }
        return (annotation.__module__ + '.' + annotation.__qualname__);
    }
    return repr(annotation);
}

